import{z as n,x as s,o as B,c as p,q as t,j as A,D as a,d as i,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"埃尔斯伯格与模糊","description":"","frontmatter":{"title":"埃尔斯伯格与模糊","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ellsberg-ambiguity.md","filePath":"econ/ellsberg-ambiguity.md","lastUpdated":1791063341000}'),d={name:"econ/ellsberg-ambiguity.md"};function m(h,E,c,F,u,C){const r=s("Mermaid");return B(),p("div",null,[E[2]||(E[2]=t('<h1 id="埃尔斯伯格与模糊" tabindex="-1">埃尔斯伯格与模糊 <a class="header-anchor" href="#埃尔斯伯格与模糊" aria-label="Permalink to &quot;埃尔斯伯格与模糊&quot;">​</a></h1><div class="epigraph"><p>已知五成红球与「红球比例不告诉你」，不是同一张彩票——未知的不是风险，是概率本身。</p><footer>—— 据 Ellsberg, Risk, Ambiguity, and the Savage Axioms, Quarterly Journal of Economics, 1961 整理</footer></div><p><a href="/econ/state-prices">上一课</a>（状态价格）。在客观 \\(\\pi\\) 与完全市场上写出 Borch 分担。本课不重写边际效用比，也不把张成再证一遍。缺口是：前面整段不确定课序都把概率当作已知数字。埃尔斯伯格的罐子表明，人会回避<strong>未知的权重</strong>。必须把这条边界钉死，同时声明：本栏主干仍用期望效用，后课保险、占优、或有要求权不改写成模糊模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两只罐子。第一只：100 球，50 红 50 黑，概率客观。第二只：100 球，红黑比例不宣布。人通常愿意对第一只赌颜色，却不愿对第二只赌同一颜色——哪怕第二只「总有一种颜色至少一半」。这与 vNM 的客观彩票不同，也与 Savage 的主观概率不同：若存在主观 \\(p\\)，对红和对黑的选择应在两只罐子间一致，实验里不一致。</p><p>缺口因此不是再估计一条 \\(r_A\\)，而是区分：<strong>风险</strong>是已知 \\(\\pi\\) 上的分布，<strong>模糊</strong>是 \\(\\pi\\) 本身未给出。上一课的 Borch、SOSD、Arrow 证券全部吃 \\(\\pi\\)。\\(\\pi\\) 一撤，那些公式没有定义，不是「风险更大」。本课只钉这一区别。</p><p><span class="marginnote">数字实例：经典问卷里，多数人宁愿对已知 50/50 的罐一赌红，不愿对比例未知的罐二赌红；换成赌黑，还是偏好罐一。若受试者真有一致的主观概率 \\(p(\\text{红})\\)，这两次选择意味着 \\(p(\\text{红})\\lt 0.5\\) 且 \\(p(\\text{黑})\\lt 0.5\\)，加起来却必须等于 1——矛盾暴露了「权重未知」。</span></p><h3 id="模糊厌恶不是更凹" tabindex="-1">模糊厌恶不是更凹 <a class="header-anchor" href="#模糊厌恶不是更凹" aria-label="Permalink to &quot;模糊厌恶不是更凹&quot;">​</a></h3><p>把第二只罐子「当成」某条更散的分布，再用 MPS 去解释回避，是偷换对象：实验里没有给出那条 \\(F\\)。凹性在已知概率内部说话；埃尔斯伯格打在概率是否存在。阿莱打的是已知概率上的独立性；两悖论不要焊成一个「人非理性」故事。</p><p><span class="marginnote">对照一句：Gilboa and Schmeidler（1989）用一族先验上的最大最小期望效用表示模糊厌恶。本栏不把它升为新主干，只标明：若放弃单一 \\(\\pi\\)，表示会改成对最坏先验取 \\(\\min\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工作策略与<a href="/econ/allais-independence">阿莱</a>对称：问卷当边界对照，市场理论默认客观或已估的 \\(\\pi\\)。检验埃尔斯伯格只需两对赌注，不必估 \\(u\\)。若坚持单一主观概率，只能说受试者「没有一致信念」。若放弃，下一条常用弱化是多先验的 maxmin，或光滑模糊。本课不展开这些表示。</p><p>不确定课序在此结束。下一课程换对象：生产集没有概率，也没有罐子。不要把技术写成模糊的 \\(Y\\)。</p>',13)),(B(),A(o,null,{default:a(()=>[l(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E4%B8%BB%E5%B9%B2%EF%BC%9A%E5%B7%B2%E7%9F%A5%20%CF%80%20%E7%9A%84%20E%20u%22%5D%20--%3E%20RISK%5B%22%E9%A3%8E%E9%99%A9%EF%BC%9ABorch%E3%80%81SOSD%E3%80%81%E5%BC%A0%E6%88%90%22%5D%0A%20%20EU%20--%3E%20EDGE%5B%22%E8%BE%B9%E7%95%8C%EF%BC%9A%CF%80%20%E6%9C%AA%E7%9F%A5%22%5D%0A%20%20EDGE%20--%3E%20ELL%5B%22%E5%9F%83%E5%B0%94%E6%96%AF%E4%BC%AF%E6%A0%BC%E7%BD%90%E5%AD%90%22%5D%0A%20%20ELL%20--%3E%20KEEP%5B%22%E4%B8%BB%E5%B9%B2%E4%BB%8D%E7%94%A8%20E%20u%22%5D%0A%20%20ELL%20--%3E%20GS%5B%22%E5%AF%B9%E7%85%A7%EF%BC%9A%E5%A4%9A%E5%85%88%E9%AA%8C%20maxmin%22%5D%0A%20%20KEEP%20--%3E%20LATER%5B%22%E4%B8%8B%E8%AF%BE%E7%A8%8B%EF%BC%9A%E7%94%9F%E4%BA%A7%E9%9B%86%20Y%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"本课不把模糊引进状态价格。后课一般均衡默认 \\(\\pi\\) 给定。也不把「不确定性」在奈特意义上写成新的商品。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"已知比例的罐子给出客观混合，独立性与线性权重适用。未知比例时，决策者面对的是一集可能的 \\(\\pi\\)，而不是 \\(\\Delta(X)\\) 里的一个点。回避第二只罐子，等于不愿对这集里的最坏元素下注。这与风险厌恶可以共存：同一人可以对第一只罐子凹、对第二只罐子再额外要求「确定的权重」。",-1)),(B(),A(o,null,{default:a(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20BET%5B%22%E5%AF%B9%E7%BA%A2%E7%90%83%E4%B8%8B%E6%B3%A8%EF%BC%8C%E9%80%89%E5%93%AA%E5%8F%AA%E7%BD%90%EF%BC%9F%22%5D%20--%3E%20U1%5B%22%E7%BD%90%E4%B8%80%EF%BC%9A50%20%E7%BA%A2%2050%20%E9%BB%91%22%5D%0A%20%20BET%20--%3E%20U2%5B%22%E7%BD%90%E4%BA%8C%EF%BC%9A%E7%BA%A2%E9%BB%91%E6%AF%94%E4%BE%8B%E4%B8%8D%E5%AE%A3%E5%B8%83%22%5D%0A%20%20U1%20--%3E%20P%5B%22%E6%A6%82%E7%8E%87%E6%98%AF%E4%B8%80%E4%B8%AA%E7%82%B9%EF%BC%9A%CF%80%20%3D%200.5%22%5D%0A%20%20U2%20--%3E%20S%5B%22%E6%A6%82%E7%8E%87%E6%98%AF%E4%B8%80%E4%B8%AA%E9%9B%86%E5%90%88%EF%BC%9A%CF%80%20%E5%8F%AF%E5%9C%A8%E5%8C%BA%E9%97%B4%E5%86%85%E6%BB%91%E5%8A%A8%22%5D%0A%20%20P%20--%3E%20OK%5B%22%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%E5%A4%9F%E7%94%A8%EF%BC%9A%E5%87%B9%E6%80%A7%E8%A7%A3%E9%87%8A%E5%9B%9E%E9%81%BF%22%5D%0A%20%20S%20--%3E%20WORST%5B%22%E5%86%B3%E7%AD%96%E8%80%85%E7%9B%AF%E4%BD%8F%E9%9B%86%E5%90%88%E9%87%8C%E6%9C%80%E5%9D%8F%E7%9A%84%20%CF%80%22%5D%0A%20%20WORST%20--%3E%20AMB%5B%22%E6%A8%A1%E7%B3%8A%E5%8E%8C%E6%81%B6%EF%BC%9A%E9%A2%9D%E5%A4%96%E7%9A%84%E4%B8%80%E5%B1%82%E5%9B%9E%E9%81%BF%EF%BC%8C%E5%8F%AF%E4%B8%8E%E5%87%B9%E6%80%A7%E5%85%B1%E5%AD%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p>对后课的含义是收口。规范层：保险与最优分担继续按 \\(\\mathbb{E}u\\) 写，因为合同与证券的支付仍按可描述的状态与（估出的）概率记账。描述层：实验室对未知权重的回避，不能拿来拒绝 Borch，就像阿莱不能拿来把 \\(r_A\\) 改成「喜欢风险」。本栏宏观与公司金融走规范层。</p><p><span class="marginnote">Ellsberg 1961 针对的是 Savage 公理，尤其是主观概率的存在，不是前景理论。引用不要把罐子写成 Kahneman–Tversky 的附录，也不要写成阿莱四张表的续篇。</span></p><p><span class="marginnote">术语翻译：模糊厌恶就是「连概率都不知道时的那份不舒服」。风险像掷一只已验明的均匀骰子，输赢规则清楚；模糊像骰子被人偷偷配过重却没告诉你怎么配——多出来的那份反感，就是模糊厌恶，它和怕输钱（凹性）是两回事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>市场数据很少直接复制两只罐子。故主干保留期望效用，不是无视实验，而是对象不同：后课的或有要求权、随机折现因子都在已给出的 \\(\\pi\\) 或已估信念上工作。若某后课改用 maxmin 或鲁棒控制，必须显式声明。</p><p>也不要把模糊写成限价簿上的「不确定谁会报价」。微观结构的未知是成交机制，不是先验集。生产课序即将开始，那里的不确定性若出现，先写成状态依存的 \\(Y_s\\)，仍默认 \\(\\pi\\)，不默认埃尔斯伯格。</p><p>主观概率一旦从数据里估出来，本课的罐子缺口就关了：估出的 \\(\\pi\\) 重新进入 \\(\\mathbb{E}u\\)，Borch 与张成照用。本课打击的是「尚未给出权重」这一段，不是打击所有贝叶斯更新。</p><p><span class="marginnote">常见误区：初学者容易把埃尔斯伯格读成「实验证明人不理性，所以期望效用作废」。文章实际只划边界：概率未给定时 \\(\\mathbb{E}u\\) 没有定义；概率一旦给出或估出，保险与分担公式照用，主干不必改写。</span></p><p>后课默认：工作表示仍是单一 \\(\\pi\\) 上的 \\(\\mathbb{E}u\\)；未知概率是已标明的边界，不自动改写分担与占优。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>未知概率不是更大的风险；Borch 与 SOSD 都吃已知 \\(\\pi\\)。</li><li>埃尔斯伯格打击主观概率的存在，不是打击凹性。</li><li>主干仍用期望效用；Gilboa–Schmeidler 只作一句对照。</li><li>不确定课序到此；下一课打开生产集。</li><li>出处：Ellsberg, <em>QJE</em>, 1961；Gilboa and Schmeidler, <em>Journal of Mathematical Economics</em>, 1989。</li></ul>',11))])}const g=n(d,[["render",m]]);export{D as __pageData,g as default};
